// ── Markdown renderer ──────────────────────────────────────────────────────
function esc(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

// ── Keyword search ────────────────────────────────────────────────────────
// Searches across every free-text field an incident has, plus the assigned
// engineer's name (so "search for Priya" works without knowing her trigram).
const SEARCH_FIELDS = [
  'title','issueContent','diagnosticsContent','resolutionContent',
  'env','whoCalled','supLink','kbUsed','sreResponse','escalated','other',
];
function incidentMatchesSearch(inc, query, userName){
  if(!query) return true;
  const hay = (SEARCH_FIELDS.map(k=>inc[k]||'').join(' ') + ' ' + (userName||'')).toLowerCase();
  // Support multi-word queries as AND — every word must appear somewhere.
  return query.toLowerCase().trim().split(/\s+/).every(word=>hay.includes(word));
}

// ── Recurrence detection ─────────────────────────────────────────────────
// Incident titles are free text (often "Oncall :: PRD : <alert> on <hostname>"
// style), so exact-match grouping rarely catches repeats. Instead we build a
// normalized "signature" per title — lowercase, strip punctuation/numbers,
// drop short/common words, sort what's left — and group incidents whose
// signatures match. This is a heuristic (title-similarity, not a true
// classification), so it's presented as such in the UI.
const RECUR_STOPWORDS = new Set([
  'a','an','the','on','in','at','to','of','for','and','or','is','was','are',
  'with','by','from','this','that','has','have','had','been','be','it','its',
  'oncall','disaster','alert','issue','incident','service','health',
]);
function titleSignature(title){
  return (title||'')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g,' ')
    .split(/\s+/)
    .filter(w => w.length>2 && !RECUR_STOPWORDS.has(w) && !/^\d+$/.test(w))
    .sort()
    .join(' ');
}
// Most-common title text within a recurrence group (falls back to the most
// recent if every title in the group is unique) — used as the group's
// display label since the raw signature isn't human-friendly.
function representativeTitle(items){
  const counts = new Map();
  items.forEach(i=>counts.set(i.title, (counts.get(i.title)||0)+1));
  let best=null, bestN=0;
  counts.forEach((n,t)=>{ if(n>bestN){ bestN=n; best=t; } });
  return bestN>1 ? best : [...items].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]?.title;
}
// Past incidents (excluding itself) sharing the same title signature —
// used by the Workspace Insights panel as a lightweight "similar incidents"
// recommendation, and to suggest a KB article if one was used before on a
// matching past incident. Rule-based on existing data, not a real model.
function findSimilarIncidents(inc, allIncidents, limit=5){
  const sig = titleSignature(inc.title);
  if(!sig) return [];
  return allIncidents
    .filter(o=>o.id!==inc.id && titleSignature(o.title)===sig)
    .sort((a,b)=>(b.date||'').localeCompare(a.date||''))
    .slice(0,limit);
}

// ── Wiki runbook matching ─────────────────────────────────────────────────
// Surfaces Wiki entries whose title/category share significant words with
// the incident's title — a simple keyword-overlap match, not semantic
// search, so it's shown as "suggested" rather than authoritative.
function findMatchingRunbooks(incidentTitle, wiki, limit=3){
  const words = (incidentTitle||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ')
    .split(/\s+/).filter(w=>w.length>3 && !RECUR_STOPWORDS.has(w));
  if(words.length===0 || !Array.isArray(wiki) || wiki.length===0) return [];
  return wiki
    .map(entry=>{
      const hay = `${entry.title||''} ${entry.cat||''}`.toLowerCase();
      const score = words.filter(w=>hay.includes(w)).length;
      return {entry,score};
    })
    .filter(s=>s.score>0)
    .sort((a,b)=>b.score-a.score)
    .slice(0,limit)
    .map(s=>s.entry);
}
// Small suggestion strip shown above the Diagnostics editor. Inserting
// appends the runbook's content (as a quoted, attributed block) to whatever
// is already in Diagnostics, rather than overwriting existing notes.
function RunbookSuggestions({incidentTitle,wiki,diagnosticsContent,onInsert}){
  const matches = useMemo(()=>findMatchingRunbooks(incidentTitle,wiki),[incidentTitle,wiki]);
  if(matches.length===0) return null;
  return (
    <div style={{padding:'10px 20px',borderBottom:'1px solid rgba(255,255,255,0.06)',background:'rgba(167,139,250,0.05)'}}>
      <div style={{fontSize:10,color:'rgba(167,139,250,0.7)',textTransform:'uppercase',letterSpacing:'0.6px',fontWeight:700,marginBottom:6}}>📚 Suggested runbooks</div>
      <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
        {matches.map(entry=>(
          <div key={entry.id} style={{display:'flex',alignItems:'center',gap:8,background:'rgba(255,255,255,0.04)',border:'1px solid rgba(255,255,255,0.1)',borderRadius:20,padding:'4px 6px 4px 12px'}}>
            <span style={{fontSize:12,color:'rgba(255,255,255,0.75)'}}>{entry.title}</span>
            <button onClick={()=>onInsert(entry)} style={{
              background:'rgba(167,139,250,0.15)',border:'1px solid rgba(167,139,250,0.35)',borderRadius:16,
              padding:'3px 10px',cursor:'pointer',color:'#c4b5fd',fontSize:11,fontWeight:700,
            }}>Insert</button>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── CSV export ────────────────────────────────────────────────────────────
function toCsvValue(v){
  const s = (v===null||v===undefined) ? '' : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g,'""')}"` : s;
}
function downloadCsv(rows, columns, filename){
  const header = columns.map(c=>toCsvValue(c.label)).join(',');
  const body = rows.map(r=>columns.map(c=>toCsvValue(c.get(r))).join(',')).join('\n');
  const blob = new Blob([header+'\n'+body], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// Converts Markdown pipe-table blocks (header row, --- separator, 1+ data
// rows) into real inline-styled <table> HTML. Runs before the rest of
// renderMd's line-based replacements, since those would otherwise mangle a
// table's newlines into <br/> soup before it's ever recognised as a table.
// Inline styles (not CSS classes) are deliberate: this same HTML is reused
// verbatim in the Outlook Email Summary (buildEmailHtml strips class
// attributes but not inline styles), so it needs to look right there too.
const MD_TABLE_STYLE = 'border-collapse:collapse;width:100%;margin:10px 0;font-size:13px;';
const MD_TABLE_TH = 'text-align:left;padding:6px 10px;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.07);font-weight:700;color:rgba(255,255,255,0.85);';
const MD_TABLE_TD = 'padding:6px 10px;border:1px solid rgba(255,255,255,0.08);color:rgba(255,255,255,0.7);';
function convertMdTables(md){
  const lines = md.split('\n');
  const isRow = l => /^\s*\|.*\|\s*$/.test(l);
  const isSep = l => /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(l);
  const cells = l => l.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(s=>s.trim());
  const out = [];
  let i = 0;
  while(i < lines.length){
    if(isRow(lines[i]) && isSep(lines[i+1]||'')){
      const header = cells(lines[i]);
      let j = i+2;
      const rows = [];
      while(j<lines.length && isRow(lines[j])){ rows.push(cells(lines[j])); j++; }
      const thead = `<thead><tr>${header.map(h=>`<th style="${MD_TABLE_TH}">${esc(h)}</th>`).join('')}</tr></thead>`;
      const tbody = `<tbody>${rows.map(r=>`<tr>${header.map((_,ci)=>`<td style="${MD_TABLE_TD}">${esc(r[ci]||'')}</td>`).join('')}</tr>`).join('')}</tbody>`;
      out.push(`<table style="${MD_TABLE_STYLE}">${thead}${tbody}</table>`);
      i = j;
    } else {
      out.push(lines[i]);
      i++;
    }
  }
  return out.join('\n');
}
function renderMd(md){
  if(!md) return '';
  let h = convertMdTables(md)
    .replace(/```(\w*)\n?([\s\S]*?)```/g,(_,l,c)=>`<pre class="ipr"${l?` data-lang="${l}"`:''}><code>${esc(c.trimEnd())}</code></pre>`)
    .replace(/`([^`]+)`/g,(_,c)=>`<code class="iic">${esc(c)}</code>`)
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/^### (.+)$/gm,'<h3 class="ih3">$1</h3>')
    .replace(/^## (.+)$/gm,'<h2 class="ih2">$1</h2>')
    .replace(/^# (.+)$/gm,'<h1 class="ih1">$1</h1>')
    .replace(/^---$/gm,'<hr class="ihr"/>')
    .replace(/^\[x\] (.+)$/gim,'<li class="ick done">$1</li>')
    .replace(/^\[ \] (.+)$/gim,'<li class="ick">$1</li>')
    .replace(/^[-*] (.+)$/gm,'<li>$1</li>')
    .replace(/^\d+\. (.+)$/gm,'<li class="iol">$1</li>')
    .replace(/^> (.+)$/gm,'<blockquote class="ibq">$1</blockquote>')
    .replace(/\n\n/g,'</p><p class="ipp">')
    .replace(/\n/g,'<br/>')
    .replace(/<br\/>(<table)/g,'$1').replace(/(<\/table>)<br\/>/g,'$1'); // a table shouldn't be wrapped in stray <br/>s from its own surrounding blank lines
  return `<p class="ipp">${h}</p>`;
}

// ── Content-format helpers ───────────────────────────────────────────────────
// issueContent/diagnosticsContent/resolutionContent now store real HTML
// (see RichEditor below), but incidents logged before this change still have
// Markdown strings in those fields. Every place that displays or edits this
// content needs to handle both without the person ever seeing a difference.
function looksLikeHtml(s){ return /<[a-z][\s\S]*>/i.test(s||''); }
function contentToHtml(raw){ return !raw ? '' : (looksLikeHtml(raw) ? raw : renderMd(raw)); }
function stripToPlainText(raw){
  if(!raw) return '';
  if(looksLikeHtml(raw)){
    const doc = new DOMParser().parseFromString(raw,'text/html');
    return (doc.body.textContent||'').replace(/\s+/g,' ').trim();
  }
  return raw.replace(/[#*`>_\-]/g,'').replace(/\s+/g,' ').trim(); // legacy Markdown — strip syntax chars
}

// ── Insert at cursor (used by the inline-code toolbar button, and by
// content that needs inserting into the WYSIWYG editor as real markup) ──────
function wrapSelectionWithTag(tag){
  const sel = window.getSelection();
  if(!sel || sel.rangeCount===0 || sel.isCollapsed) return; // needs an actual selection to wrap
  const range = sel.getRangeAt(0);
  const el = document.createElement(tag);
  try{ range.surroundContents(el); }catch(e){ /* selection spans element boundaries — skip rather than corrupt the DOM */ }
}

// ── Clean pasted HTML (e.g. an Outlook email) for insertion as real markup ──
// Outlook copies a full HTML fragment to the clipboard alongside plain text.
// Since the editor below is itself HTML-native (not Markdown), pasted content
// can be inserted directly rather than lossily converted to a text format —
// this only strips presentational cruft (inline colours/fonts that would
// clash with the app's dark theme, Outlook's mso-* noise, scripts) while
// preserving real structure: tables, bold, links, lists, headings.
//
// Outlook/Word HTML is notorious for wrapping the actual data table inside
// one or more outer LAYOUT tables (often literally 1 row × 1 cell, purely
// for spacing/borders). isDataTable() below distinguishes a genuine data
// table from a layout wrapper; wrappers are treated as transparent and
// walked through until a real table is found, however deep it's nested.
function isDataTable(table){
  const rows = [...table.rows];
  if(rows.length===0) return false;
  // The only real problem case is a nested <table> inside a cell (a genuine
  // layout wrapper). <p>/<div>-wrapped text is normal even in real Outlook/
  // Word data cells, so those must NOT disqualify a table here.
  if(!rows.every(tr => tr.cells.length>0 && [...tr.cells].every(c => !c.querySelector('table')))) return false;
  return rows.length>1 || rows[0].cells.length>1; // more than one row, or one row with multiple columns
}
function htmlTableToCleanHtml(table){
  const cell = s => esc(s.replace(/\u00A0/g,' ').replace(/[ \t\r\n]+/g,' ').trim());
  const rows = [...table.rows].map(tr => [...tr.cells].map(c => cell(c.textContent)));
  if(rows.length===0) return '';
  const [header, ...body] = rows;
  const th = header.map(h=>`<th style="${MD_TABLE_TH}">${h}</th>`).join('');
  const tb = body.map(r=>`<tr>${header.map((_,i)=>`<td style="${MD_TABLE_TD}">${r[i]||''}</td>`).join('')}</tr>`).join('');
  return `<table style="${MD_TABLE_STYLE}"><thead><tr>${th}</tr></thead><tbody>${tb}</tbody></table>`;
}
function cleanPastedHtml(html){
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const walk = (node) => {
    if(node.nodeType===3) return esc(node.textContent.replace(/\u00A0/g,' ').replace(/[ \t\r\n]+/g,' '));
    if(node.nodeType!==1) return ''; // not an element
    const kids = () => [...node.childNodes].map(walk).join('').trim();
    switch(node.tagName.toLowerCase()){
      case 'script': case 'style': return '';
      case 'br': return '<br/>';
      case 'table': return isDataTable(node) ? htmlTableToCleanHtml(node) : kids(); // layout wrapper → transparent, recurse to find the real table inside
      case 'tr': return kids();
      case 'td': case 'th': return kids()+' ';
      case 'p': case 'div': { const t=kids(); return t ? `<p>${t}</p>` : ''; }
      case 'h1': return `<h1>${kids()}</h1>`;
      case 'h2': return `<h2>${kids()}</h2>`;
      case 'h3': return `<h3>${kids()}</h3>`;
      case 'b': case 'strong': { const t=kids(); return t ? `<strong>${t}</strong>` : ''; }
      case 'i': case 'em': { const t=kids(); return t ? `<em>${t}</em>` : ''; }
      case 'u': return kids();
      case 'a': { const href=node.getAttribute('href'), t=kids(); return (href && t) ? `<a href="${esc(href)}" target="_blank" rel="noreferrer">${t}</a>` : t; }
      case 'li': return `<li>${kids()}</li>`;
      case 'ul': return `<ul>${kids()}</ul>`;
      case 'ol': return `<ol>${kids()}</ol>`;
      case 'blockquote': return `<blockquote>${kids()}</blockquote>`;
      case 'code': return `<code>${kids()}</code>`;
      case 'img': return ''; // dropped — use the Screenshot gallery for images, not inline in notes
      default: return kids();
    }
  };
  return walk(doc.body);
}

// ── .docx extractor ────────────────────────────────────────────────────────
async function extractDocx(buf){
  const b=new Uint8Array(buf), entries=[];
  let i=0;
  while(i<b.length-30){
    if(b[i]===0x50&&b[i+1]===0x4B&&b[i+2]===0x03&&b[i+3]===0x04){
      const comp=b[i+8]|(b[i+9]<<8), cs=b[i+18]|(b[i+19]<<8)|(b[i+20]<<16)|(b[i+21]<<24);
      const nl=b[i+26]|(b[i+27]<<8), el=b[i+28]|(b[i+29]<<8);
      const name=new TextDecoder().decode(b.slice(i+30,i+30+nl));
      const off=i+30+nl+el;
      entries.push({name,comp,cs,off}); i=off+cs;
    } else i++;
  }
  const doc=entries.find(e=>e.name==='word/document.xml');
  if(!doc) throw new Error('Not a valid .docx');
  let xb=b.slice(doc.off,doc.off+doc.cs);
  if(doc.comp===8){
    const ds=new DecompressionStream('deflate-raw');
    const w=ds.writable.getWriter(), r=ds.readable.getReader();
    w.write(xb); w.close();
    const chunks=[]; let done=false;
    while(!done){const{value,done:d}=await r.read(); if(value)chunks.push(value); done=d;}
    const tot=chunks.reduce((a,c)=>a+c.length,0);
    const out=new Uint8Array(tot); let of2=0;
    for(const c of chunks){out.set(c,of2);of2+=c.length;}
    xb=out;
  }
  const xml=new TextDecoder().decode(xb), lines=[];
  const pr=/<w:p[ >][\s\S]*?<\/w:p>/g; let pm;
  while((pm=pr.exec(xml))!==null){
    const p=pm[0], sm=p.match(/w:styleId="([^"]+)"/), st=sm?sm[1]:'';
    const ts=[]; const tr=/<w:t[^>]*>([\s\S]*?)<\/w:t>/g; let tm;
    while((tm=tr.exec(p))!==null) ts.push(tm[1]);
    const l=ts.join('').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
    if(!l.trim()){lines.push('');continue;}
    if(/Heading1/i.test(st)) lines.push(`# ${l}`);
    else if(/Heading2/i.test(st)) lines.push(`## ${l}`);
    else if(/Heading3/i.test(st)) lines.push(`### ${l}`);
    else lines.push(l);
  }
  return lines.join('\n').replace(/\n{3,}/g,'\n\n').trim();
}

