// ── Rich editor ────────────────────────────────────────────────────────────
// Content is stored as real HTML (not Markdown) so paste — from Outlook,
// Word, anywhere — keeps its actual structure natively via the browser's own
// paste handling, rather than round-tripping through a lossy text format.
// Legacy incidents logged before this change still have Markdown in these
// fields; contentToHtml() (see above) transparently upgrades them for
// editing here, and the same helper is used wherever this content displays
// elsewhere (Detail view, Email Summary) so nothing looks broken.
function RichEditor({value,onChange,placeholder}){
  const editorRef=useRef(null), fi=useRef(null);
  // Deliberately NOT seeded with `value` — must differ from any real value
  // (including '') so the very first effect run below (on mount) actually
  // populates the DOM with the incident's existing content, instead of
  // being incorrectly treated as "no change needed" because both sides
  // started out equal.
  const lastEmitted=useRef(undefined);

  // Keep the DOM in sync with value changes that originate OUTSIDE this
  // editor (Import, Insert runbook, switching in from a freshly-loaded
  // incident) — guarded so it never fights the user's own typing: when a
  // keystroke fires onInput below, value is set to exactly what the DOM
  // already contains, so this effect is a no-op for that render.
  useEffect(()=>{
    const el=editorRef.current; if(!el) return;
    if(value===lastEmitted.current) return;
    el.innerHTML = contentToHtml(value);
    lastEmitted.current = value;
  },[value]);

  const emit=()=>{
    const html = editorRef.current?.innerHTML || '';
    lastEmitted.current = html;
    onChange(html);
  };

  const insertHtmlAtCursor=(html)=>{
    editorRef.current?.focus();
    document.execCommand('insertHTML', false, html);
    emit();
  };

  const handleFile=async(e)=>{
    const f=e.target.files?.[0]; if(!f) return; e.target.value='';
    const n=f.name.toLowerCase();
    let md='';
    if(n.endsWith('.md')||n.endsWith('.txt')||n.endsWith('.markdown')){ md = await f.text(); }
    else if(n.endsWith('.docx')){
      try{ md = await extractDocx(await f.arrayBuffer()); }
      catch(err){ alert('Could not parse .docx\n'+err.message); return; }
    } else { alert('Supported: .md  .txt  .docx'); return; }
    insertHtmlAtCursor(renderMd(md));
  };

  return (
    <div style={{display:'flex',flexDirection:'column',flex:1,minHeight:0,background:'#0d1117'}}>
      {/* Toolbar */}
      <div style={{
        display:'flex',alignItems:'center',gap:2,padding:'0 10px',
        height:40,background:'rgba(255,255,255,0.03)',
        borderBottom:'1px solid rgba(255,255,255,0.07)',flexShrink:0,flexWrap:'nowrap',
      }}>
        {TOOLBAR_ITEMS.map((t,i)=> t.sep
          ? <div key={i} style={{width:1,height:16,background:'rgba(255,255,255,0.1)',margin:'0 3px',flexShrink:0}}/>
          : <button key={i} title={t.title}
              onMouseDown={ev=>{ev.preventDefault(); editorRef.current?.focus(); t.cmd(); emit();}}
              style={{background:'transparent',border:'none',borderRadius:5,padding:'3px 7px',
                cursor:'pointer',color:'rgba(255,255,255,0.45)',flexShrink:0,
                transition:'color .1s,background .1s',...t.s,
                ':hover':{color:'white'}}}
              onMouseEnter={e=>e.currentTarget.style.color='rgba(255,255,255,0.85)'}
              onMouseLeave={e=>e.currentTarget.style.color='rgba(255,255,255,0.45)'}
            >{t.label}</button>
        )}
        <div style={{flex:1}}/>
        <button onClick={()=>fi.current?.click()} style={{
          display:'flex',alignItems:'center',gap:5,
          background:'rgba(59,130,246,0.12)',border:'1px solid rgba(59,130,246,0.3)',
          borderRadius:6,padding:'4px 11px',cursor:'pointer',
          color:'#60a5fa',fontSize:11,fontWeight:600,flexShrink:0,
        }}>↑ Import</button>
        <input ref={fi} type="file" accept=".md,.txt,.markdown,.docx" style={{display:'none'}} onChange={handleFile}/>
      </div>

      {/* Content area — WYSIWYG: what you see here is exactly what's stored
          and exactly what shows elsewhere (Detail view, Email Summary) */}
      <div
        ref={editorRef}
        contentEditable
        suppressContentEditableWarning
        className="inc-pv"
        onInput={emit}
        onPaste={e=>{
          const html = e.clipboardData?.getData('text/html');
          if(!html) return; // no rich data on the clipboard — let default plain-text paste happen
          let cleaned='';
          try{ cleaned = cleanPastedHtml(html); }catch(err){ cleaned=''; }
          if(cleaned){ e.preventDefault(); insertHtmlAtCursor(cleaned); return; }
          // Conversion produced nothing usable (or threw) — fall back to the
          // plain-text clipboard variant rather than silently swallowing the
          // paste. Only intercept if there IS a plain-text fallback to use;
          // otherwise let the browser's own default paste behaviour run.
          const plain = e.clipboardData.getData('text/plain');
          if(plain){ e.preventDefault(); document.execCommand('insertText', false, plain); emit(); }
        }}
        data-placeholder={placeholder}
        style={{
          flex:1,overflowY:'auto',outline:'none',
          padding:'18px 24px',fontSize:13,lineHeight:1.8,
          color:'rgba(255,255,255,0.82)',
        }}
      />
      <style>{`
        [contenteditable]:empty:before{content:attr(data-placeholder);color:rgba(255,255,255,0.2)}
        .inc-pv h1{font-size:20px;font-weight:700;color:#fff;margin:16px 0 8px;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:6px}
        .inc-pv h2{font-size:16px;font-weight:700;color:#fff;margin:14px 0 6px}
        .inc-pv h3{font-size:13px;font-weight:600;color:rgba(255,255,255,0.7);margin:10px 0 4px}
        .inc-pv p{margin:0 0 10px}
        .inc-pv ul,.inc-pv ol{margin:0 0 10px;padding-left:22px}
        .inc-pv li{margin-bottom:3px;color:rgba(255,255,255,0.75)}
        .inc-pv blockquote{border-left:3px solid var(--accent);padding:4px 14px;color:rgba(255,255,255,0.45);margin:8px 0;font-style:italic;background:rgba(59,130,246,0.06);border-radius:0 4px 4px 0}
        .inc-pv hr{border:none;border-top:1px solid rgba(255,255,255,0.08);margin:14px 0}
        .inc-pv code{background:#161b22;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:1px 6px;font-family:"DM Mono",monospace;font-size:12px;color:#79c0ff}
        .inc-pv table{border-collapse:collapse;margin:10px 0}
        .inc-pv a{color:var(--accent)}
        /* Legacy classes — content converted from pre-existing Markdown
           incidents via renderMd() still carries these; keep them styled
           identically to the plain-tag rules above. */
        .inc-pv .ih1{font-size:20px;font-weight:700;color:#fff;margin:16px 0 8px;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:6px}
        .inc-pv .ih2{font-size:16px;font-weight:700;color:#fff;margin:14px 0 6px}
        .inc-pv .ih3{font-size:13px;font-weight:600;color:rgba(255,255,255,0.7);margin:10px 0 4px}
        .inc-pv .ipp{margin:0 0 10px}
        .inc-pv .iol{list-style:decimal}
        .inc-pv .ick{list-style:none;margin-left:4px;padding-left:20px;position:relative}
        .inc-pv .ick::before{content:"☐";position:absolute;left:0;color:rgba(255,255,255,0.3)}
        .inc-pv .ick.done{text-decoration:line-through;color:rgba(255,255,255,0.35)}
        .inc-pv .ick.done::before{content:"☑";color:#22c55e}
        .inc-pv .ibq{border-left:3px solid var(--accent);padding:4px 14px;color:rgba(255,255,255,0.45);margin:8px 0;font-style:italic;background:rgba(59,130,246,0.06);border-radius:0 4px 4px 0}
        .inc-pv .ihr{border:none;border-top:1px solid rgba(255,255,255,0.08);margin:14px 0}
        .inc-pv pre.ipr{background:#161b22;border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:14px 16px;overflow-x:auto;margin:10px 0}
        .inc-pv pre.ipr::before{content:attr(data-lang);display:block;font-size:9px;color:rgba(255,255,255,0.3);margin-bottom:8px;text-transform:uppercase;letter-spacing:1.5px;font-family:monospace}
        .inc-pv pre.ipr code{font-family:"DM Mono",monospace;font-size:12px;color:#e6edf3;white-space:pre}
        .inc-pv code.iic{background:#161b22;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:1px 6px;font-family:"DM Mono",monospace;font-size:12px;color:#79c0ff}
      `}</style>
    </div>
  );
}

// ── Screenshot gallery (multi-upload, no limit) ──────────────────────────────
// Available on Issue, Diagnostics, and Resolution. Accepts multi-select and
// paste, compresses each image before storing (same as the old single
// upload), and spans the full width of the fields grid so thumbnails have
// room. Reads via readShots() so legacy single-screenshot incidents still show.
function ScreenshotGallery({field,form,setForm}){
  const fi = useRef(null);
  const [busy,setBusy] = useState(false);
  const shots = readShots(form, field.key, field.legacyKey);

  const addFiles = async(fileList)=>{
    const files = [...fileList].filter(f=>f.type.startsWith('image/'));
    if(files.length===0) return;
    setBusy(true);
    try{
      const compressed = await Promise.all(files.map(f=>compressScreenshot(f)));
      setForm(f=>({...f,[field.key]:[...(Array.isArray(f[field.key])?f[field.key]:[]), ...compressed]}));
    }catch(err){ alert('Could not read one of those images.\n'+err.message); }
    finally{ setBusy(false); }
  };

  // Removing needs care: index 0 may be the legacy single-screenshot string
  // rather than a member of the gallery array.
  const removeAt = (i)=>{
    const legacyCount = (field.legacyKey && form[field.legacyKey]) ? 1 : 0;
    if(i < legacyCount){ setForm(f=>({...f,[field.legacyKey]:''})); return; }
    const arrIdx = i - legacyCount;
    setForm(f=>({...f,[field.key]:(Array.isArray(f[field.key])?f[field.key]:[]).filter((_,n)=>n!==arrIdx)}));
  };

  return (
    <div style={{gridColumn: shots.length>0 ? '1 / -1' : 'auto'}}>
      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:5}}>
        <span style={fieldLabelStyle}>{field.label}</span>
        {shots.length>0 && <span style={{fontSize:10,color:'rgba(255,255,255,0.3)'}}>{shots.length} attached</span>}
      </div>
      <div
        onPaste={e=>{ const f=e.clipboardData?.files; if(f?.length) addFiles(f); }}
        onDragOver={e=>e.preventDefault()}
        onDrop={e=>{ e.preventDefault(); if(e.dataTransfer?.files?.length) addFiles(e.dataTransfer.files); }}
        title="Select multiple, drag & drop, or paste. Click a thumbnail to open full size."
        style={{display:'flex',flexWrap:'wrap',gap:8,alignItems:'flex-start'}}
      >
        {shots.map((src,i)=>(
          <div key={i} style={{position:'relative'}}>
            <img src={src} alt={`Screenshot ${i+1}`} onClick={()=>window.open(src,'_blank')}
              style={{height:64,borderRadius:8,border:'1px solid rgba(255,255,255,0.15)',cursor:'zoom-in',display:'block'}}/>
            <button onClick={()=>removeAt(i)} title="Remove"
              style={{
                position:'absolute',top:-6,right:-6,width:20,height:20,borderRadius:'50%',
                background:'#1a1a2e',border:'1px solid rgba(239,68,68,0.5)',color:'#fca5a5',
                cursor:'pointer',fontSize:11,lineHeight:1,display:'flex',alignItems:'center',justifyContent:'center',padding:0,
              }}>✕</button>
          </div>
        ))}
        {shots.length>0 ? (
          <button onClick={()=>fi.current?.click()} disabled={busy} style={{
            height:64,minWidth:64,borderRadius:8,cursor:busy?'default':'pointer',
            background:'rgba(255,255,255,0.03)',border:'1px dashed rgba(255,255,255,0.2)',
            color:'rgba(255,255,255,0.45)',fontSize:16,
            display:'flex',alignItems:'center',justifyContent:'center',
          }}>{busy?'…':'⬆'}</button>
        ) : (
          <button onClick={()=>fi.current?.click()} disabled={busy} style={{...structFieldBtn,width:'100%',display:'flex',alignItems:'center',justifyContent:'center',gap:6}}>
            {busy ? '…' : '⬆ Add'}
          </button>
        )}
        <input ref={fi} type="file" accept="image/*" multiple style={{display:'none'}}
          onChange={e=>{ addFiles(e.target.files); e.target.value=''; }}/>
      </div>
    </div>
  );
}

// ── Structured fields bar (shown above the editor on Issue/Diagnostics/Resolution) ──
function StructuredFieldsBar({fields,form,setForm}){
  const set = (key,v)=>setForm(f=>({...f,[key]:v}));

  return (
    <div style={{
      display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(150px, 1fr))', gap:10,
      padding:'10px 20px', flexShrink:0,
      borderBottom:'1px solid rgba(255,255,255,0.06)',
      background:'rgba(255,255,255,0.015)',
    }}>
      {fields.map(field=>(
        field.type==='images' ? (
          <ScreenshotGallery key={field.key} field={field} form={form} setForm={setForm}/>
        ) : (
        <div key={field.key} style={{display:'flex',flexDirection:'column',gap:5}}>
          <span style={fieldLabelStyle}>{field.label}</span>
          {field.type==='select' ? (
            IMPACT_COLORS[form[field.key]] ? (
              <select value={form[field.key]||''} onChange={e=>set(field.key,e.target.value)} style={pillSelectStyle(IMPACT_COLORS[form[field.key]])}>
                {field.options.map(o=><option key={o} value={o}>{o||'Select…'}</option>)}
              </select>
            ) : (
              <select value={form[field.key]||''} onChange={e=>set(field.key,e.target.value)} style={structFieldSel}>
                {field.options.map(o=><option key={o} value={o}>{o||'Select…'}</option>)}
              </select>
            )
          ) : field.type==='datetime' ? (
            <div style={{display:'flex',flexDirection:'column',gap:2}}>
              <input type="datetime-local" value={form[field.key]||''} onChange={e=>set(field.key,e.target.value)} style={{...structFieldInput,colorScheme:'dark'}}/>
              {form[field.key] && (
                <span style={{fontSize:9.5,color:'rgba(255,255,255,0.35)'}}>→ {fmtUTC(form[field.key])}</span>
              )}
            </div>
          ) : field.type==='computed' ? (
            <div style={{...structFieldInput,background:'transparent',border:'1px solid transparent',padding:'8px 0',color:'rgba(255,255,255,0.5)',fontStyle:'italic'}}>
              {field.compute(form) || '—'}
            </div>
          ) : (
            <input value={form[field.key]||''} onChange={e=>set(field.key,e.target.value)} placeholder={field.placeholder} style={structFieldInput}/>
          )}
        </div>
        )
      ))}
    </div>
  );
}
